<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {localDateKey,localDayBounds} from '@/lib/businessDay'
import {useI18n} from '@/lib/i18n'
const {pick,formatCurrency}=useI18n()
type Row={id:string;full_name:string;invoice_count:number;invoiced:number;return_count:number;refunds:number;net_sales:number;average_bill:number;return_rate:number;cash:number;card:number;mobile:number;credit:number}
const from=ref(localDateKey()),to=ref(localDateKey()),rows=ref<Row[]>([]),busy=ref(false),error=ref(''),mix=ref(false)
const totals=computed(()=>rows.value.reduce((s,r)=>({invoices:s.invoices+r.invoice_count,sales:s.sales+r.invoiced,refunds:s.refunds+r.refunds,net:s.net+r.net_sales}),{invoices:0,sales:0,refunds:0,net:0}))
onMounted(load)
async function load(){busy.value=true;error.value='';try{const [start]=localDayBounds(from.value);const [,end]=localDayBounds(to.value);rows.value=await invoke<Row[]>('cashier_performance',{start,end})}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><div class="tool-terminal documents-terminal"><header class="tool-header"><div><h1>{{pick('Cashier Performance','کیشئر کی کارکردگی')}}</h1><p>{{pick('Local business-day range · refunds assigned to the original selling cashier','مقامی کاروباری دن · واپسی اصل فروخت کرنے والے کیشئر کے کھاتے میں')}}</p></div></header><form class="commercial-filters" @submit.prevent="load"><label>{{pick('From','سے')}}<input v-model="from" required type="date"/></label><label>{{pick('To','تک')}}<input v-model="to" required type="date" :min="from"/></label><label><input v-model="mix" type="checkbox"/> {{pick('Payment mix','ادائیگی کی تقسیم')}}</label><button class="bg-primary" :disabled="busy">{{pick('Run report','رپورٹ دکھائیں')}}</button></form><p v-if="error" role="alert" class="commercial-error">{{error}}</p><p class="commercial-hint">{{pick('Invoiced sales use the selected business days. Refunds use their completed-refund date and may relate to older sales. Net sales = invoiced − those refunds. Average bill = invoiced ÷ invoices. Return rate = share of period invoices with a completed refund by period end. Credit is invoiced, not collected cash.','فروخت منتخب کاروباری دنوں کی ہے۔ واپسی مکمل تصفیے کی تاریخ سے ہے اور پرانی فروخت کی ہو سکتی ہے۔ خالص فروخت = فروخت − واپسی۔ اوسط بل = فروخت ÷ بل۔ واپسی شرح منتخب مدت کے بلوں میں مدت کے اختتام تک واپسی والے بلوں کا تناسب ہے۔ ادھار فروخت نقد وصولی نہیں۔')}}</p><div class="commercial-table-scroll"><p v-if="busy" role="status">{{pick('Loading…','لوڈ ہو رہا ہے…')}}</p><table v-else><thead><tr><th>{{pick('Cashier','کیشئر')}}</th><th>{{pick('Invoices','بل')}}</th><th>{{pick('Invoiced','فروخت')}}</th><th>{{pick('Refunds / count','واپسی / تعداد')}}</th><th>{{pick('Net sales','خالص فروخت')}}</th><th>{{pick('Average bill','اوسط بل')}}</th><th>{{pick('Return rate','واپسی شرح')}}</th><template v-if="mix"><th>{{pick('Cash','نقد')}}</th><th>{{pick('Card','کارڈ')}}</th><th>{{pick('Mobile','موبائل')}}</th><th>{{pick('Credit','ادھار')}}</th></template></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.full_name}}</td><td>{{r.invoice_count}}</td><td>{{formatCurrency(r.invoiced)}}</td><td>{{formatCurrency(r.refunds)}} / {{r.return_count}}</td><td>{{formatCurrency(r.net_sales)}}</td><td>{{formatCurrency(r.average_bill)}}</td><td>{{r.return_rate}}%</td><template v-if="mix"><td>{{formatCurrency(r.cash)}}</td><td>{{formatCurrency(r.card)}}</td><td>{{formatCurrency(r.mobile)}}</td><td>{{formatCurrency(r.credit)}}</td></template></tr><tr v-if="!rows.length"><td :colspan="mix?11:7" class="commercial-empty">{{pick('No cashier activity for this range.','اس مدت میں کیشئر کی کوئی سرگرمی نہیں۔')}}</td></tr></tbody></table></div><footer class="tool-summary"><div><small>{{pick('Invoices','بل')}}</small><strong>{{totals.invoices}}</strong></div><div><small>{{pick('Invoiced','فروخت')}}</small><strong>{{formatCurrency(totals.sales)}}</strong></div><div><small>{{pick('Refunds','واپسی')}}</small><strong>{{formatCurrency(totals.refunds)}}</strong></div><div><small>{{pick('Net sales','خالص فروخت')}}</small><strong>{{formatCurrency(totals.net)}}</strong></div></footer></div></template>
